#pragma once
// UI language (RU / EN) and the viewer's one string table (Strings.cpp, generated by src/lang/gen_strings.py from
// src/lang/*.tsv). No ImGui: the core translates its messages with it, the UI's ui:: wrappers (Lang.h) its labels.
#include <format>
#include <string>
#include <utility>
#include <vector>

enum class UiLang { Ru, En };
void SetUiLang(UiLang lang);
UiLang GetUiLang();

// Translation of an English UI string; "label##id" translates the label and keeps the id (IDs stay stable only where
// "###id" is used: windows). Unknown strings come back as they are (and are listed by MissingTranslations()).
const char* T(const char* en);
inline const char* T(const std::string& en) { return T(en.c_str()); }
const char* TrNoRecord(const char* s); // T() for data that may or may not be a UI string (not listed as missing)
template <class... A> std::string TF(const char* en, const A&... a)
{
    try { return std::vformat(T(en), std::make_format_args(a...)); }
    catch (const std::format_error&) { return std::vformat(en, std::make_format_args(a...)); } // a broken translation: English
}

// Hotkey registry (App::RegisterHotkeys): command description -> key name, used for tooltips of matching controls.
void SetCommandKeys(std::vector<std::pair<std::string, std::string>> descriptionToKey);
// Tooltip of a control label: the string table, else a registry command of that name; empty if none.
std::string TipOf(const char* label);
// The key a control is looked up by: its label, or the id when the label is only an icon / empty ("<icon>##Open model")
std::string LabelKey(const char* label);
// A control shown without an own tooltip (listed by MissingTips; non-ASCII keys are data, ignored)
void NoteMissingTip(const std::string& key);

// ui-script "lang": what was shown this session without a translation / without an own tooltip; table size
std::vector<std::string> MissingTranslations();
std::vector<std::string> MissingTips();
std::pair<size_t, size_t> TableStats(); // (strings, tooltips)
